    def process_val(val):
        if isinstance(val, (int, float)):
            return float(val * 2)
        if isinstance(val, list):
            return [process_val(i) for i in val]
        if isinstance(val, str):
            nums = re.findall(r"[-+]?\d*\.\d+|\d+", val)
            if nums:
                for n in nums:
                    val = val.replace(n, str(float(n) * 2))
            return val
        return val

    processed_data = {k: process_val(v) for k, v in data.items()}

    try:
        df = pd.DataFrame([processed_data])
        return df
    except Exception:
        return pd.DataFrame()

